            pid = facts[0]['pid']
        f = None
        for x in facts:
            if x['pid'] == pid:
                f = x
        b['product_id'] = pid
        try:
            vars['last_promise_pid'] = pid
        except Exception:
            pass
        good = f is not None
        dt = str(b.get('date') or '').strip()[:10]
        b['date'] = dt
        kind = str(b.get('amount_kind') or '').strip().lower()
        b.pop('amount_kind', None)
        amt = None
        if f is not None and kind == 'full':
            amt = float(f['past'])
        elif f is not None and kind == 'floor':
            amt = float(f['floor'])
        else:
            try:
                amt = round(float(str(b.get('amount')).replace(',', '')), 2)
            except Exception:
                amt = None
                good = False
        if amt is not None:
            b['amount'] = amt
        if f is not None:
            if dt not in f['valid']:
                good = False
            if amt is not None and (amt < float(f['floor']) - 0.001 or amt > float(f['past']) + 0.001):
                good = False
            try:
                done = json.loads(str(vars.get('promises_json') or '[]'))
                if any(str(x.get('pid')) == pid for x in done):
                    good = False
            except Exception:
                pass
        if not good:
            b['date'] = 'REJECTED'
except Exception:
    pass

